  1→import { test, expect, Browser } from '@playwright/test';
  2→import {
  3→  createTestAccount,
  4→  closeTestAccounts,
  5→  navigateToShared,
  6→  navigateToFiles,
  7→  type TestAccount,
  8→} from '../utils/multi-account';
  9→import { createTestTextFile, cleanupTestFiles } from '../utils/test-files';
 10→import { FileListPage } from '../page-objects/file-browser/file-list.page';
 11→import { UploadZonePage } from '../page-objects/file-browser/upload-zone.page';
 12→import { ContextMenuPage } from '../page-objects/file-browser/context-menu.page';
 13→import { CreateFolderDialogPage } from '../page-objects/dialogs/create-folder-dialog.page';
 14→import { ShareDialogPage } from '../page-objects/dialogs/share-dialog.page';
 15→import { InviteLinkTabPage } from '../page-objects/dialogs/invite-link-tab.page';
 16→import { InvitePageObject } from '../page-objects/pages/invite.page';
 17→import { SharedFileBrowserPage } from '../page-objects/file-browser/shared-file-browser.page';
 18→
 19→/**
 20→ * Invite Link Sharing Workflow E2E Test Suite
 21→ *
 22→ * Tests the complete invite link lifecycle:
 23→ * - ShareDialog tab bar UI (switching between Direct Share and Invite Link)
 24→ * - Invite link creation (URL generated, copied to clipboard)
 25→ * - Invite landing page (unauthenticated view, error states)
 26→ * - Invite claim (authenticated user auto-claims, redirect to /shared)
 27→ * - Invite management (list active invites, revoke)
 28→ * - Error states (invalid URL, non-existent token, already-claimed, self-claim)
 29→ *
 30→ * Accounts:
 31→ * - Alice: sharer (creates content and invite links)
 32→ * - Dave: primary invite recipient (claims via invite link)
 33→ * - Eve: secondary recipient (for folder invite, already-claimed test)
 34→ *
 35→ * Each test account gets its own browser context (isolated cookies/storage).
 36→ */
 37→
 38→/** Parse an invite URL to extract token and ephemeral key */
 39→function parseInviteUrl(url: string): { token: string; ephemeralKey: string } {
 40→  // URL format: http://localhost:5173/#/invite/TOKEN?key=KEY
 41→  const hashPart = url.split('#')[1]; // /invite/TOKEN?key=KEY
 42→  const [path, query] = hashPart.split('?');
 43→  const token = path.split('/invite/')[1];
 44→  const params = new URLSearchParams(query);
 45→  const ephemeralKey = params.get('key')!;
 46→  return { token, ephemeralKey };
 47→}
 48→
 49→test.describe.serial('Invite Link Sharing Workflow', () => {
 50→  let browser: Browser;
 51→  let alice: TestAccount;
 52→  let dave: TestAccount;
 53→  let eve: TestAccount;
 54→
 55→  // Page objects for Alice
 56→  let aliceFileList: FileListPage;
 57→  let aliceUploadZone: UploadZonePage;
 58→  let aliceContextMenu: ContextMenuPage;
 59→  let aliceCreateFolderDialog: CreateFolderDialogPage;
 60→  let aliceShareDialog: ShareDialogPage;
 61→  let aliceInviteTab: InviteLinkTabPage;
