import {
  Injectable,
  HttpException,
  HttpStatus,
  BadRequestException,
  ConflictException,
  Logger,
  Inject,
  forwardRef,
} from '@nestjs/common';
import { InjectRepository } from '@nestjs/typeorm';
import { Repository } from 'typeorm';
import { FolderIpns } from './entities/folder-ipns.entity';
import {
  PublishIpnsDto,
  PublishIpnsResponseDto,
  BatchPublishIpnsDto,
  BatchPublishIpnsResponseDto,
} from './dto';
import { RepublishService } from '../republish/republish.service';
import { DelegatedRoutingClient } from './delegated-routing.client';
import { parseIpnsRecord } from './ipns-record-parser';

@Injectable()
export class IpnsService {
  private readonly logger = new Logger(IpnsService.name);

  constructor(
    @InjectRepository(FolderIpns)
    private readonly folderIpnsRepository: Repository<FolderIpns>,
    private readonly delegatedRouting: DelegatedRoutingClient,
    @Inject(forwardRef(() => RepublishService))
    private readonly republishService: RepublishService
  ) {}

  /**
   * Publish a pre-signed IPNS record to the IPFS network via delegated routing
   * and track the folder in the database for TEE republishing
   */
  async publishRecord(userId: string, dto: PublishIpnsDto): Promise<PublishIpnsResponseDto> {
    // Validate base64 record
    let recordBytes: Uint8Array;
    try {
      recordBytes = Uint8Array.from(atob(dto.record), (c) => c.charCodeAt(0));
    } catch {
      throw new BadRequestException('Invalid base64-encoded record');
    }

    // Save to DB first so resolve always has a fallback, even if delegated
    // routing fails (e.g. rate-limited, network error, DHT propagation delay).
    const folder = await this.upsertFolderIpns(
      userId,
      dto.ipnsName,
      dto.metadataCid,
      dto.encryptedIpnsPrivateKey,
      dto.keyEpoch,
      'folder',
      dto.expectedSequenceNumber
    );

    // Publish to delegated routing API (best-effort — DB is the reliable source)
    try {
      await this.delegatedRouting.publish(dto.ipnsName, recordBytes);
    } catch (error) {
      this.logger.warn(
        `Delegated routing publish failed for ${dto.ipnsName}, DB record saved: ${error instanceof Error ? error.message : String(error)}`
      );
    }

    return {
      success: true,
      ipnsName: dto.ipnsName,
      sequenceNumber: folder.sequenceNumber,
    };
  }

  /**
   * Batch publish multiple IPNS records with concurrency-limited processing.
   * Supports partial success: individual record failures do not fail the batch.
   * Processes up to 10 records concurrently.
   */
  async publishBatch(
    userId: string,
    dto: BatchPublishIpnsDto
  ): Promise<BatchPublishIpnsResponseDto> {
    const results: PublishIpnsResponseDto[] = [];
    let totalSucceeded = 0;
    let totalFailed = 0;

    const CONCURRENCY = 10;

    // Process records in batches of CONCURRENCY
    for (let i = 0; i < dto.records.length; i += CONCURRENCY) {
      const batch = dto.records.slice(i, i + CONCURRENCY);

      const settled = await Promise.allSettled(
        batch.map(async (entry) => {
          // Validate base64 record
          let recordBytes: Uint8Array;
          try {
            recordBytes = Uint8Array.from(atob(entry.record), (c) => c.charCodeAt(0));
          } catch {
            throw new BadRequestException(`Invalid base64-encoded record for ${entry.ipnsName}`);
          }

          // Save to DB first so resolve always has a fallback
          const folder = await this.upsertFolderIpns(
            userId,
            entry.ipnsName,
            entry.metadataCid,
            entry.encryptedIpnsPrivateKey,
            entry.keyEpoch,
            entry.recordType ?? 'folder',
            entry.expectedSequenceNumber
          );

          // Publish to delegated routing (best-effort)
          try {
            await this.delegatedRouting.publish(entry.ipnsName, recordBytes);
          } catch (error) {
            this.logger.warn(
              `Delegated routing publish failed for ${entry.ipnsName}, DB record saved: ${error instanceof Error ? error.message : String(error)}`
            );
          }

          return {
            success: true,
            ipnsName: entry.ipnsName,
            sequenceNumber: folder.sequenceNumber,
          } as PublishIpnsResponseDto;
        })
      );

      for (let j = 0; j < settled.length; j++) {
        const result = settled[j];
        if (result.status === 'fulfilled') {
          results.push(result.value);
          totalSucceeded++;
        } else {
          const reason = result.reason;
          // If any record (especially a folder record) has a conflict, fail the entire batch
          if (reason instanceof ConflictException) {
            throw reason;
          }
          const ipnsName = batch[j]?.ipnsName ?? 'unknown';
          this.logger.warn(
            `Batch publish failed for ${ipnsName}: ${reason instanceof Error ? reason.message : String(reason)}`
          );
          results.push({
            success: false,
            ipnsName,
            sequenceNumber: '0',
          });
          totalFailed++;
        }
      }
    }

    return { results, totalSucceeded, totalFailed };
  }

  /**
   * Create or update a folder/file IPNS entry.
   * Handles both folder metadata and per-file metadata IPNS records.
   */
  private async upsertFolderIpns(
    userId: string,
    ipnsName: string,
    metadataCid: string,
    encryptedIpnsPrivateKey?: string,
    keyEpoch?: number,
    recordType: 'folder' | 'file' = 'folder',
    expectedSequenceNumber?: string
  ): Promise<FolderIpns> {
    const existing = await this.getFolderIpns(userId, ipnsName);

    // Conflict detection: when expectedSequenceNumber is provided, verify it matches
    if (existing && expectedSequenceNumber !== undefined) {
      const expected = BigInt(expectedSequenceNumber);
      const current = BigInt(existing.sequenceNumber);
      if (expected !== current) {
        throw new ConflictException({
          statusCode: 409,
          message: 'Sequence number mismatch: folder was modified by another device',
          currentSequenceNumber: existing.sequenceNumber,
          expectedSequenceNumber,
        });
      }
    }

    if (existing) {
      // Update existing entry
      existing.latestCid = metadataCid;
      existing.sequenceNumber = (BigInt(existing.sequenceNumber) + 1n).toString();
      existing.recordType = recordType;
      existing.updatedAt = new Date();

      // Only update encrypted key if provided (e.g., on key rotation)
      if (encryptedIpnsPrivateKey && keyEpoch !== undefined) {
        existing.encryptedIpnsPrivateKey = Buffer.from(encryptedIpnsPrivateKey, 'hex');
        existing.keyEpoch = keyEpoch;
      }

      const saved = await this.folderIpnsRepository.save(existing);

      // Auto-enroll for TEE republishing when encrypted key is provided
      if (encryptedIpnsPrivateKey && keyEpoch !== undefined) {
        this.republishService
          .enrollFolder(
            userId,
            ipnsName,
            Buffer.from(encryptedIpnsPrivateKey, 'hex'),
            keyEpoch,
            metadataCid,
            saved.sequenceNumber
          )
          .catch((err) =>
            this.logger.warn(
              `Failed to enroll ${recordType} ${ipnsName} for republishing: ${err.message}`
            )
          );
      }

      return saved;
    }

    // Create new entry
    const folder = this.folderIpnsRepository.create({
      userId,
      ipnsName,
      latestCid: metadataCid,
      sequenceNumber: '0',
      encryptedIpnsPrivateKey: encryptedIpnsPrivateKey
        ? Buffer.from(encryptedIpnsPrivateKey, 'hex')
        : null,
      keyEpoch: keyEpoch ?? null,
      isRoot: false, // Root folder is tracked in Vault entity
      recordType,
    });

    const saved = await this.folderIpnsRepository.save(folder);

    // Auto-enroll for TEE republishing when encrypted key is provided
    if (encryptedIpnsPrivateKey && keyEpoch !== undefined) {
      this.republishService
        .enrollFolder(
          userId,
          ipnsName,
          Buffer.from(encryptedIpnsPrivateKey, 'hex'),
          keyEpoch,
          metadataCid,
          saved.sequenceNumber
        )
        .catch((err) =>
          this.logger.warn(
            `Failed to enroll ${recordType} ${ipnsName} for republishing: ${err.message}`
          )
        );
    }

    return saved;
  }

  /**
   * Get a folder IPNS entry by user and IPNS name
   */
  async getFolderIpns(userId: string, ipnsName: string): Promise<FolderIpns | null> {
    return this.folderIpnsRepository.findOne({
      where: { userId, ipnsName },
    });
  }

  /**
   * Get all folder IPNS entries for a user (for TEE republishing)
   */
  async getAllFolderIpns(userId: string): Promise<FolderIpns[]> {
    return this.folderIpnsRepository.find({
      where: { userId },
      order: { createdAt: 'ASC' },
    });
  }

  /**
   * Resolve an IPNS name to its current CID via delegated routing,
   * falling back to the DB-cached CID when delegated routing is unavailable
   * or when the record is not found in the DHT.
   * Returns null if the IPNS name is not found anywhere (404)
   */
  async resolveRecord(ipnsName: string): Promise<{
    cid: string;
    sequenceNumber: string;
    signatureV2?: string;
    data?: string;
    pubKey?: string;
  } | null> {
    let result: {
      cid: string;
      sequenceNumber: string;
      signatureV2?: string;
      data?: string;
      pubKey?: string;
    } | null = null;

    try {
      const recordBytes = await this.delegatedRouting.resolve(ipnsName);
      if (recordBytes) {
        result = this.parseIpnsRecordBytes(recordBytes);
        this.logger.debug(`IPNS name resolved successfully: ${ipnsName} -> ${result.cid}`);
      }
    } catch (error) {
      // Fall back to DB cache on BAD_GATEWAY (delegated routing failures)
      if (error instanceof HttpException && error.getStatus() === HttpStatus.BAD_GATEWAY) {
        this.logger.warn(`Delegated routing failed for ${ipnsName}, falling back to DB cache`);
      } else {
        throw error;
      }
    }

    // Always check DB cache — it's written synchronously during publish
    // and may be ahead of the network (delegated routing can serve stale records)
    const cached = await this.folderIpnsRepository.findOne({
      where: { ipnsName },
    });

    if (result && cached?.latestCid) {
      // Both sources available — prefer the one with the higher sequence number
      const networkSeq = BigInt(result.sequenceNumber);
      const dbSeq = BigInt(cached.sequenceNumber);
      if (dbSeq > networkSeq) {
        this.logger.log(
          `DB cache has newer sequence (${dbSeq} > ${networkSeq}) for ${ipnsName}, using DB: ${cached.latestCid}`
        );
        return { cid: cached.latestCid, sequenceNumber: cached.sequenceNumber };
      }
      return result;
    }

    if (result) {
      return result;
    }

    // Delegated routing returned null (404) or threw BAD_GATEWAY — try DB cache
    if (cached?.latestCid) {
      this.logger.log(`Resolved ${ipnsName} from DB cache: ${cached.latestCid}`);
      return { cid: cached.latestCid, sequenceNumber: cached.sequenceNumber };
    }

    return null;
  }

  /**
   * Parse an IPNS record to extract CID and sequence number
   * Uses inline protobuf decoder — no external dependencies
   */
  private parseIpnsRecordBytes(recordBytes: Uint8Array): {
    cid: string;
    sequenceNumber: string;
    signatureV2?: string;
    data?: string;
    pubKey?: string;
  } {
    try {
      const record = parseIpnsRecord(recordBytes);

      // Extract CID from the Value field (format: /ipfs/<cid>)
      const valuePath = record.value;
      const cidMatch = valuePath.match(/\/ipfs\/([a-zA-Z0-9]+)/);
      if (!cidMatch) {
        this.logger.error('Failed to extract CID from IPNS record value');
        throw new HttpException('Invalid IPNS record format', HttpStatus.BAD_GATEWAY);
      }

      const cid = cidMatch[1];
      const sequenceNumber = String(record.sequence ?? 0n);

      // Base64-encode signature fields if present
      const signatureV2 = record.signatureV2
        ? Buffer.from(record.signatureV2).toString('base64')
        : undefined;
      const data = record.data ? Buffer.from(record.data).toString('base64') : undefined;
      const pubKey = record.pubKey ? Buffer.from(record.pubKey).toString('base64') : undefined;

      this.logger.debug(`Parsed IPNS record: cid=${cid}, sequenceNumber=${sequenceNumber}`);
      return { cid, sequenceNumber, signatureV2, data, pubKey };
    } catch (error) {
      if (error instanceof HttpException) {
        throw error;
      }
      this.logger.error(`Failed to parse IPNS record: ${error}`);
      throw new HttpException('Invalid IPNS record format', HttpStatus.BAD_GATEWAY);
    }
  }
}

import {
  Controller,
  Post,
  Get,
  Body,
  Query,
  UseGuards,
  Request,
  NotFoundException,
} from '@nestjs/common';
import { ApiTags, ApiOperation, ApiResponse, ApiBearerAuth, ApiQuery } from '@nestjs/swagger';
import { Throttle, ThrottlerGuard } from '@nestjs/throttler';
import { JwtAuthGuard } from '../auth/guards/jwt-auth.guard';
import { IpnsService } from './ipns.service';
import {
  PublishIpnsDto,
  PublishIpnsResponseDto,
  BatchPublishIpnsDto,
  BatchPublishIpnsResponseDto,
  ResolveIpnsQueryDto,
  ResolveIpnsResponseDto,
} from './dto';
import { MetricsService } from '../metrics/metrics.service';
import { RequestWithUser } from '../common/types';

@ApiTags('IPNS')
@ApiBearerAuth()
@UseGuards(JwtAuthGuard, ThrottlerGuard)
@Controller('ipns')
export class IpnsController {
  constructor(
    private readonly ipnsService: IpnsService,
    private readonly metricsService: MetricsService
  ) {}

  // [SECURITY: HIGH-04] Rate limit IPNS publish to prevent abuse
  // Each publish makes external HTTP calls to delegated-ipfs.dev
  @Throttle({ default: { limit: 10, ttl: 60000 } }) // 10 publishes per minute per user
  @Post('publish')
  @ApiOperation({
    summary: 'Publish IPNS record',
    description:
      'Relay a pre-signed IPNS record to the IPFS network via delegated routing. ' +
      'The client signs the record locally; backend relays to delegated-ipfs.dev and tracks ' +
      'the folder for TEE republishing.',
  })
  @ApiResponse({
    status: 200,
    description: 'IPNS record published successfully',
    type: PublishIpnsResponseDto,
  })
  @ApiResponse({
    status: 400,
    description: 'Bad Request - Invalid record format or missing required fields',
  })
  @ApiResponse({
    status: 401,
    description: 'Unauthorized - JWT token required',
  })
  @ApiResponse({
    status: 409,
    description:
      'Conflict - expectedSequenceNumber does not match current server sequence number. ' +
      'Response body includes currentSequenceNumber for client re-sync.',
  })
  @ApiResponse({
    status: 502,
    description: 'Bad Gateway - Failed to publish to delegated routing',
  })
  async publishRecord(
    @Request() req: RequestWithUser,
    @Body() dto: PublishIpnsDto
  ): Promise<PublishIpnsResponseDto> {
    const result = await this.ipnsService.publishRecord(req.user.id, dto);
    this.metricsService.ipnsPublishes.inc({ type: 'single' });
    return result;
  }

  // [SECURITY: HIGH-04] Rate limit batch publish - lower limit since each batch can have up to 200 records
  @Throttle({ default: { limit: 5, ttl: 60000 } }) // 5 batch publishes per minute per user
  @Post('publish-batch')
  @ApiOperation({
    summary: 'Batch publish IPNS records',
    description:
      'Publish multiple IPNS records (folder and/or file) in a single API call. ' +
      'Supports up to 200 records per batch with concurrency-limited processing. ' +
      'Partial success is allowed: individual record failures do not fail the batch.',
  })
  @ApiResponse({
    status: 200,
    description: 'Batch publish results with per-record outcomes',
    type: BatchPublishIpnsResponseDto,
  })
  @ApiResponse({
    status: 400,
    description: 'Bad Request - Invalid record format or batch exceeds 200 entries',
  })
  @ApiResponse({
    status: 401,
    description: 'Unauthorized - JWT token required',
  })
  @ApiResponse({
    status: 409,
    description:
      'Conflict - a folder record in the batch has an expectedSequenceNumber that does not match ' +
      'the current server sequence number. The entire batch is rejected.',
  })
  @ApiResponse({
    status: 502,
    description: 'Bad Gateway - Delegated routing failures (partial results may be returned)',
  })
  async publishBatch(
    @Request() req: RequestWithUser,
    @Body() dto: BatchPublishIpnsDto
  ): Promise<BatchPublishIpnsResponseDto> {
    const result = await this.ipnsService.publishBatch(req.user.id, dto);
    this.metricsService.ipnsPublishes.inc({ type: 'batch' }, result.totalSucceeded);
    return result;
  }

  // [SECURITY: HIGH-04] Rate limit IPNS resolve - higher limit than publish since read-only
  @Throttle({ default: { limit: 30, ttl: 60000 } }) // 30 resolves per minute per user
  @Get('resolve')
  @ApiOperation({
    summary: 'Resolve IPNS name',
    description:
      'Resolve an IPNS name to its current CID via delegated routing. ' +
      'Returns the CID and sequence number of the current IPNS record.',
  })
  @ApiQuery({
    name: 'ipnsName',
    description:
      'IPNS name to resolve. Supports CIDv1 IPNS names starting with "k51..." (PeerID-style) or "bafzaa..." (IPNS key CID).',
    example: 'REDACTED',
  })
  @ApiResponse({
    status: 200,
    description: 'IPNS name resolved successfully',
    type: ResolveIpnsResponseDto,
  })
  @ApiResponse({
    status: 400,
    description: 'Bad Request - Invalid IPNS name format',
  })
  @ApiResponse({
    status: 401,
    description: 'Unauthorized - JWT token required',
  })
  @ApiResponse({
    status: 404,
    description: 'Not Found - IPNS name not published or not found in routing network',
  })
  @ApiResponse({
    status: 502,
    description: 'Bad Gateway - Failed to resolve from delegated routing',
  })
  async resolveRecord(@Query() query: ResolveIpnsQueryDto): Promise<ResolveIpnsResponseDto> {
    const result = await this.ipnsService.resolveRecord(query.ipnsName);

    if (!result) {
      throw new NotFoundException('IPNS name not found in routing network');
    }

    // Track resolve source: if signatureV2 is present, it came from the network
    const source = result.signatureV2 ? 'network' : 'db_cache';
    this.metricsService.ipnsResolves.inc({ source });

    // Include signature fields as all-or-nothing bundle for client verification
    const hasSigData = result.signatureV2 && result.data && result.pubKey;
    return {
      success: true,
      cid: result.cid,
      sequenceNumber: result.sequenceNumber,
      ...(hasSigData && {
        signatureV2: result.signatureV2,
        data: result.data,
        pubKey: result.pubKey,
      }),
    };
  }
}

