        latestCid: 'bafyFRESH',
        sequenceNumber: '10',
      });

      const result = await service.resolveRecord(testIpnsName);

      expect(result).not.toBeNull();
      expect(result!.cid).toBe('bafyFRESH');
      expect(result!.sequenceNumber).toBe('10');
