  1→//! Encrypted device registry client.
  2→//!
  3→//! Manages registration of the desktop device in the ECIES-encrypted
  4→//! device registry stored on IPFS/IPNS. The registry enables cross-device
  5→//! awareness: the web app can see the desktop as a known device, and the
  6→//! desktop can participate in device approval flows.
  7→//!
  8→//! IMPORTANT: Registry operations must NEVER block login.
  9→//! All errors are caught and logged by the caller (tokio::spawn wrapper).
 10→
 11→pub mod types;
 12→
 13→use std::sync::Arc;
 14→
 15→use base64::Engine;
 16→
 17→use crate::api::client::ApiClient;
 18→use crate::api::ipns::IpnsPublishRequest;
 19→use crate::crypto;
 20→use types::{DeviceAuthStatus, DeviceEntry, DevicePlatform, DeviceRegistry};
 21→
 22→/// Register this desktop device in the encrypted device registry.
 23→///
 24→/// Steps:
 25→/// 1. Derive registry IPNS keypair via HKDF
 26→/// 2. Try to resolve existing registry from IPNS
 27→/// 3. Build device entry for this desktop
 28→/// 4. Update or create registry with the device entry
 29→/// 5. Encrypt registry with user's public key (ECIES)
 30→/// 6. Upload to IPFS and publish IPNS record
 31→///
 32→/// This function should be called via `tokio::spawn` so failures never block login.
 33→pub async fn register_device(
 34→    api: &Arc<ApiClient>,
 35→    private_key: &[u8; 32],
 36→    public_key: &[u8],
 37→    _user_id: &str,
 38→) -> Result<(), String> {
 39→    // 1. Derive registry IPNS keypair via HKDF
 40→    let (reg_ipns_priv, _reg_ipns_pub, reg_ipns_name) =
 41→        crypto::hkdf::derive_registry_ipns_keypair(private_key)
 42→            .map_err(|e| format!("Registry IPNS derivation failed: {}", e))?;
 43→
 44→    // 2. Try to resolve existing registry from IPNS
 45→    let existing_registry = match fetch_and_decrypt_registry(api, &reg_ipns_name, private_key).await
 46→    {
 47→        Ok(reg) => Some(reg),
 48→        Err(_) => None, // No registry exists yet (first device)
 49→    };
 50→
 51→    // 3. Build device entry for this desktop
 52→    let device_id = get_or_create_device_id();
 53→    let device_entry = DeviceEntry {
 54→        device_id: device_id.clone(),
 55→        public_key: hex::encode(public_key),
 56→        name: get_device_name(),
 57→        platform: get_device_platform(),
 58→        app_version: env!("CARGO_PKG_VERSION").to_string(),
 59→        device_model: get_device_model(),
 60→        ip_hash: String::new(), // Not tracked for desktop
 61→        status: if existing_registry.is_none() {
 62→            DeviceAuthStatus::Authorized // First device auto-authorized
 63→        } else {
 64→            DeviceAuthStatus::Pending
 65→        },
 66→        created_at: now_ms(),
 67→        last_seen_at: now_ms(),
 68→        revoked_at: None,
 69→        revoked_by: None,
 70→    };
 71→
 72→    // 4. Build updated registry
 73→    let mut registry = existing_registry.unwrap_or(DeviceRegistry {
 74→        version: "v1".to_string(),
 75→        sequence_number: 0,
 76→        devices: vec![],
 77→    });
 78→
 79→    // Update existing device entry or add new one
 80→    if let Some(existing) = registry
 81→        .devices
 82→        .iter_mut()
 83→        .find(|d| d.device_id == device_id)
 84→    {
 85→        existing.last_seen_at = now_ms();
 86→        existing.app_version = env!("CARGO_PKG_VERSION").to_string();
 87→    } else {
 88→        registry.devices.push(device_entry);
 89→    }
 90→    registry.sequence_number += 1;
 91→
 92→    // 5. Encrypt registry with user's public key (ECIES)
 93→    let registry_json = serde_json::to_vec(&registry)
 94→        .map_err(|e| format!("Registry serialization failed: {}", e))?;
 95→    let encrypted = crypto::ecies::wrap_key(&registry_json, public_key)
 96→        .map_err(|e| format!("Registry encryption failed: {}", e))?;
 97→
 98→    // 6. Upload encrypted registry to IPFS
 99→    let cid = crate::api::ipfs::upload_content(api, &encrypted).await?;
100→
101→    // 7. Create and publish IPNS record
102→    let reg_ipns_priv_arr: [u8; 32] = reg_ipns_priv.as_slice()
103→        .try_into()
104→        .map_err(|_| "Invalid registry IPNS key length".to_string())?;
105→    let value = format!("/ipfs/{}", cid);
106→    let record =
107→        crypto::ipns::create_ipns_record(&reg_ipns_priv_arr, &value, registry.sequence_number, 86_400_000)
108→            .map_err(|e| format!("IPNS record creation failed: {}", e))?;
109→    let marshaled = crypto::ipns::marshal_ipns_record(&record)
110→        .map_err(|e| format!("IPNS record marshaling failed: {}", e))?;
111→    let record_base64 = base64::engine::general_purpose::STANDARD.encode(&marshaled);
112→
113→    // Device registry publishes do not use conflict detection -- the registry
114→    // IPNS namespace is separate from folder metadata, and the registry write
115→    // is already serialized by the caller.
116→    let publish_req = IpnsPublishRequest {
117→        ipns_name: reg_ipns_name,
118→        record: record_base64,
119→        metadata_cid: cid,
120→        encrypted_ipns_private_key: None,
121→        key_epoch: None,
122→        expected_sequence_number: None,
123→    };
124→    match crate::api::ipns::publish_ipns(api, &publish_req).await? {
125→        crate::api::ipns::PublishResult::Success => {}
126→        crate::api::ipns::PublishResult::Conflict { .. } => {
127→            log::warn!("Unexpected conflict on device registry publish");
128→        }
129→    }
130→
131→    log::info!(
132→        "Device registered in encrypted registry (device_id: {})",
133→        device_id
134→    );
135→    Ok(())
136→}
137→
138→/// Fetch and decrypt existing registry from IPNS.
139→async fn fetch_and_decrypt_registry(
140→    api: &ApiClient,
141→    ipns_name: &str,
142→    private_key: &[u8; 32],
143→) -> Result<DeviceRegistry, String> {
144→    let resolve = crate::api::ipns::resolve_ipns(api, ipns_name).await?;
145→    let encrypted = crate::api::ipfs::fetch_content(api, &resolve.cid).await?;
146→    let decrypted = crypto::ecies::unwrap_key(&encrypted, private_key)
147→        .map_err(|e| format!("Registry decryption failed: {}", e))?;
148→    serde_json::from_slice(&decrypted).map_err(|e| format!("Registry parse failed: {}", e))
149→}
150→
151→/// Generate a random UUID v4 string.
152→fn generate_uuid_v4() -> String {
153→    let bytes = crypto::utils::generate_random_bytes(16);
154→    format!(
155→        "{:02x}{:02x}{:02x}{:02x}-{:02x}{:02x}-4{:01x}{:02x}-{:02x}{:02x}-{:02x}{:02x}{:02x}{:02x}{:02x}{:02x}",
156→        bytes[0], bytes[1], bytes[2], bytes[3],
157→        bytes[4], bytes[5],
158→        bytes[6] & 0x0f, bytes[7],
159→        (bytes[8] & 0x3f) | 0x80, bytes[9],
160→        bytes[10], bytes[11], bytes[12], bytes[13], bytes[14], bytes[15],
161→    )
162→}
163→
164→/// Get or create a persistent device ID stored in macOS Keychain.
165→///
166→/// Uses the `keyring` crate with service "cipherbox-desktop" and key "device-id".
167→/// If no device ID exists, generates a UUID v4 and stores it.
168→///
169→/// In debug builds, skips Keychain entirely and uses an ephemeral UUID.
170→/// This avoids macOS Keychain permission prompts that fire on every rebuild
171→/// (each build produces a new binary signature).
172→fn get_or_create_device_id() -> String {
173→    #[cfg(debug_assertions)]
174→    {
175→        log::info!("Debug mode: using ephemeral device ID (no Keychain access)");
176→        return generate_uuid_v4();
177→    }
178→
179→    #[cfg(not(debug_assertions))]
180→    {
181→        let entry = match keyring::Entry::new("cipherbox-desktop", "device-id") {
182→            Ok(e) => e,
183→            Err(e) => {
184→                log::warn!("Keychain entry creation failed: {}. Using ephemeral ID.", e);
185→                return generate_uuid_v4();
186→            }
187→        };
188→
189→        match entry.get_password() {
190→            Ok(id) if !id.is_empty() => id,
191→            _ => {
192→                let uuid = generate_uuid_v4();
193→
194→                let _ = entry.delete_credential();
195→                if let Err(e) = entry.set_password(&uuid) {
196→                    log::warn!(
197→                        "Failed to store device ID in Keychain: {}. Using ephemeral ID.",
198→                        e
199→                    );
200→                }
201→                uuid
202→            }
203→        }
204→    }
205→}
206→
207→/// Get the device name from the system hostname.
208→fn get_device_name() -> String {
209→    hostname::get()
210→        .map(|h| h.to_string_lossy().to_string())
211→        .unwrap_or_else(|_| "CipherBox Desktop".to_string())
212→}
213→
214→/// Get the device platform enum for the current OS.
215→fn get_device_platform() -> DevicePlatform {
216→    #[cfg(target_os = "macos")]
217→    { DevicePlatform::Macos }
218→    #[cfg(target_os = "windows")]
219→    { DevicePlatform::Windows }
220→    #[cfg(target_os = "linux")]
221→    { DevicePlatform::Linux }
222→    #[cfg(not(any(target_os = "macos", target_os = "windows", target_os = "linux")))]
223→    { DevicePlatform::Web }
224→}
225→
226→/// Get a device model string for the current platform.
227→///
228→/// Returns a platform-specific generic string. Could be enhanced with
229→/// `sysinfo` crate for specific model names (e.g., "MacBook Pro").
230→fn get_device_model() -> String {
231→    #[cfg(target_os = "macos")]
232→    { "macOS Desktop".to_string() }
233→    #[cfg(target_os = "windows")]
234→    { "Windows Desktop".to_string() }
235→    #[cfg(target_os = "linux")]
236→    { "Linux Desktop".to_string() }
237→    #[cfg(not(any(target_os = "macos", target_os = "windows", target_os = "linux")))]
238→    { "Desktop".to_string() }
239→}
240→
241→/// Get the current time in milliseconds since Unix epoch.
242→fn now_ms() -> u64 {
243→    std::time::SystemTime::now()
244→        .duration_since(std::time::UNIX_EPOCH)
245→        .map(|d| d.as_millis() as u64)
246→        .unwrap_or(0)
247→}
