  1→//! FUSE filesystem trait implementation for CipherBoxFS.
  2→//!
  3→//! Delegates to category-specific modules:
  4→//! - `read_ops`: init, destroy, lookup, getattr, open, read, release, flush, access, getxattr, listxattr
  5→//! - `write_ops`: setattr, write, create, unlink, mkdir, rmdir, rename
  6→//! - `dir_ops`: readdir, opendir, releasedir, statfs
  7→//!
  8→//! IMPORTANT: All async operations use block_on from the tokio runtime.
  9→//! FUSE requires synchronous replies, so we block on async operations as needed.
 10→
 11→#[cfg(feature = "fuse")]
 12→pub(crate) mod implementation {
 13→    use fuser::{
 14→        Filesystem, ReplyAttr, ReplyCreate, ReplyData, ReplyDirectory,
 15→        ReplyEntry, ReplyEmpty, ReplyOpen, ReplyStatfs, ReplyWrite, ReplyXattr, Request,
 16→    };
 17→    use std::ffi::OsStr;
 18→    use std::time::{Duration, SystemTime};
 19→
 20→    use crate::fuse::CipherBoxFS;
 21→
 22→    // ── Shared constants and helpers ────────────────────────────────────────
 23→
 24→    /// TTL for FUSE attribute/entry cache replies on files.
 25→    pub const FILE_TTL: Duration = Duration::from_secs(60);
 26→
 27→    /// TTL for directory attribute/entry cache replies.
 28→    pub const DIR_TTL: Duration = Duration::from_secs(0);
 29→
 30→    /// Pick the right TTL based on whether the inode is a directory.
 31→    pub fn ttl_for_is_dir(is_dir: bool) -> Duration {
 32→        if is_dir { DIR_TTL } else { FILE_TTL }
 33→    }
 34→
 35→    /// Get the current process UID (macOS only).
 36→    pub fn current_uid() -> u32 {
 37→        unsafe { libc::getuid() }
 38→    }
 39→
 40→    /// Get the current process GID (macOS only).
 41→    pub fn current_gid() -> u32 {
 42→        unsafe { libc::getgid() }
 43→    }
 44→
 45→    /// Maximum time for a network operation before returning EIO.
 46→    pub const NETWORK_TIMEOUT: Duration = Duration::from_secs(3);
 47→
 48→    /// Run an async operation with a timeout, blocking the current thread.
 49→    pub fn block_with_timeout<F, T>(rt: &tokio::runtime::Handle, fut: F) -> Result<T, String>
 50→    where
 51→        F: std::future::Future<Output = Result<T, String>>,
 52→    {
 53→        rt.block_on(async {
 54→            match tokio::time::timeout(NETWORK_TIMEOUT, fut).await {
 55→                Ok(result) => result,
 56→                Err(_) => Err("Operation timed out".to_string()),
 57→            }
 58→        })
 59→    }
 60→
 61→    /// Helper: Fetch, decrypt, and populate a folder's children.
 62→    pub fn fetch_and_populate_folder(
 63→        fs: &mut CipherBoxFS,
 64→        ino: u64,
 65→        ipns_name: &str,
 66→        folder_key: &[u8],
 67→    ) -> Result<(), String> {
 68→        let api = fs.api.clone();
 69→        let ipns_name_owned = ipns_name.to_string();
 70→        let folder_key_owned = folder_key.to_vec();
 71→        let private_key = fs.private_key.clone();
 72→
 73→        let rt = fs.rt.clone();
 74→        let result = block_with_timeout(&rt, async {
 75→            let resolve_resp =
 76→                crate::api::ipns::resolve_ipns(&api, &ipns_name_owned).await?;
 77→            let encrypted_bytes =
 78→                crate::api::ipfs::fetch_content(&api, &resolve_resp.cid).await?;
 79→            Ok::<(Vec<u8>, String), String>((encrypted_bytes, resolve_resp.cid))
 80→        })?;
 81→
 82→        let (encrypted_bytes, cid) = result;
 83→
 84→        let metadata = crate::fuse::decrypt::decrypt_metadata_from_ipfs_public(&encrypted_bytes, &folder_key_owned)?;
 85→
 86→        fs.metadata_cache.set(&ipns_name.to_string(), metadata.clone(), cid);
 87→
 88→        fs.inodes.populate_folder(ino, &metadata, &private_key, &fs.public_key, false)?;
 89→
 90→        let unresolved = fs.inodes.get_unresolved_file_pointers();
 91→        if !unresolved.is_empty() {
 92→            log::info!("Resolving {} FilePointer(s) for folder ino {}", unresolved.len(), ino);
 93→            resolve_file_pointers_blocking(fs, &unresolved, &folder_key_owned)?;
 94→        }
 95→
 96→        Ok(())
 97→    }
 98→
 99→    /// Resolve FilePointer inodes by fetching and decrypting per-file IPNS metadata.
100→    pub fn resolve_file_pointers_blocking(
101→        fs: &mut CipherBoxFS,
102→        unresolved: &[(u64, String)],
103→        folder_key: &[u8],
104→    ) -> Result<(), String> {
105→        let api = fs.api.clone();
106→        let rt = fs.rt.clone();
107→        let folder_key_arr: [u8; 32] = folder_key.try_into()
108→            .map_err(|_| "Invalid folder key length for FilePointer resolution".to_string())?;
109→
110→        for (ino, ipns_name) in unresolved {
111→            let resolve_result = block_with_timeout(&rt, async {
112→                let resp = crate::api::ipns::resolve_ipns(&api, ipns_name).await?;
113→                let encrypted_bytes = crate::api::ipfs::fetch_content(&api, &resp.cid).await?;
114→                Ok::<Vec<u8>, String>(encrypted_bytes)
115→            });
116→
117→            match resolve_result {
118→                Ok(encrypted_bytes) => {
119→                    match crate::fuse::decrypt::decrypt_file_metadata_from_ipfs_public(&encrypted_bytes, &folder_key_arr) {
120→                        Ok(file_meta) => {
121→                            fs.inodes.resolve_file_pointer(
122→                                *ino,
123→                                file_meta.cid,
124→                                file_meta.file_key_encrypted,
125→                                file_meta.file_iv,
126→                                file_meta.size,
127→                                file_meta.encryption_mode,
128→                                file_meta.versions,
129→                            );
130→                        }
131→                        Err(e) => {
132→                            log::warn!(
133→                                "FilePointer resolution failed for ino {} ({}): {}",
134→                                ino, ipns_name, e
135→                            );
136→                        }
137→                    }
138→                }
139→                Err(e) => {
140→                    log::warn!(
141→                        "FilePointer IPNS resolve failed for ino {} ({}): {}",
142→                        ino, ipns_name, e
143→                    );
144→                }
145→            }
146→        }
147→
148→        Ok(())
149→    }
