230→/// Merge local children onto remote children to resolve a concurrent-edit conflict.
231→///
232→/// Strategy (last-writer-wins per child, additive merge):
233→/// - Start with remote children as base
234→/// - For each child also present locally (by IPNS name): use local version (handles rename)
235→/// - For each child present locally but NOT in remote: add it (new file/folder from this device)
236→/// - For each child present in remote but NOT locally: preserve remote (without tombstones we
237→///   cannot distinguish "local deleted it" from "local never saw it", so we err on the side of
238→///   preserving data to avoid dropping concurrent additions)
239→///
240→/// This is a purely additive merge -- no deletions are performed.
241→#[cfg(any(feature = "fuse", feature = "winfsp"))]
242→fn merge_folder_children(
243→    local: &crate::crypto::folder::FolderMetadata,
244→    remote: crate::crypto::folder::FolderMetadata,
245→) -> crate::crypto::folder::FolderMetadata {
246→    use crate::crypto::folder::FolderChild;
247→
248→    /// Extract the stable IPNS identifier for a child entry.
249→    fn child_ipns_key(child: &FolderChild) -> &str {
250→        match child {
251→            FolderChild::Folder(f) => f.ipns_name.as_str(),
252→            FolderChild::File(f) => f.file_meta_ipns_name.as_str(),
253→        }
254→    }
255→
256→    // Build lookup map keyed by IPNS name for local children.
257→    let local_by_ipns: std::collections::HashMap<String, &FolderChild> = local
258→        .children
259→        .iter()
260→        .map(|c| (child_ipns_key(c).to_string(), c))
261→        .collect();
262→
263→    let mut merged: Vec<FolderChild> = Vec::new();
264→    let mut seen_ipns: std::collections::HashSet<String> = std::collections::HashSet::new();
265→
266→    // Walk remote children in original order (deterministic iteration).
267→    // If local has a version of this child, use local (handles rename/modify).
268→    // Otherwise, preserve the remote child -- without tombstones we cannot
269→    // distinguish "local deleted it" from "local never saw it", so we err on
270→    // the side of preserving data to avoid dropping concurrent additions.
271→    for remote_child in &remote.children {
272→        let ipns = child_ipns_key(remote_child).to_string();
273→        if let Some(local_child) = local_by_ipns.get(&ipns) {
274→            merged.push((*local_child).clone());
275→        } else {
276→            // Preserve remote child to avoid dropping concurrent additions.
277→            merged.push(remote_child.clone());
278→        }
279→        seen_ipns.insert(ipns);
280→    }
281→
282→    // Add any locally-added children that don't exist in remote (new files/folders).
283→    for local_child in &local.children {
284→        let ipns = child_ipns_key(local_child).to_string();
285→        if !seen_ipns.contains(&ipns) {
286→            merged.push(local_child.clone());
287→        }
288→    }
289→
290→    crate::crypto::folder::FolderMetadata {
291→        version: "v2".to_string(),
292→        children: merged,
293→    }
294→}
