760→    /// Drain completed upload notifications and update inode CIDs + caches.
761→    /// Also flushes the debounced publish queue when uploads settle.
762→    pub fn drain_upload_completions(&mut self) {
763→        while let Ok(result) = self.upload_rx.try_recv() {
764→            log::debug!(
765→                "Upload complete: ino {} -> CID {}",
766→                result.ino,
767→                result.new_cid
768→            );
769→            // Update inode CID — only if write_generation matches.
770→            // This prevents stale uploads from overwriting newer content state
771→            // (e.g., TC01 upload completing after TC02 has truncated+rewritten).
772→            if let Some(inode) = self.inodes.get_mut(result.ino) {
773→                if inode.write_generation == result.write_generation {
774→                    if let inode::InodeKind::File { ref mut cid, .. } = inode.kind {
775→                        *cid = result.new_cid.clone();
776→                    }
777→                } else {
778→                    log::debug!(
779→                        "Skipping stale upload for ino {} (gen {} != current {})",
780→                        result.ino, result.write_generation, inode.write_generation
781→                    );
782→                }
783→            }
784→            // Move plaintext from pending_content to content_cache
785→            if let Some(plaintext) = self.pending_content.remove(&result.ino) {
786→                self.content_cache.set(&result.new_cid, plaintext);
787→            }
788→            // Old file CID is now preserved as a version entry -- do NOT unpin it.
789→            // Only unpin CIDs from pruned versions that exceeded MAX_VERSIONS_PER_FILE.
790→            for pruned_cid in &result.pruned_cids {
791→                let api = self.api.clone();
792→                let cid = pruned_cid.clone();
793→                self.rt.spawn(async move {
794→                    let _ = crate::api::ipfs::unpin_content(&api, &cid).await;
795→                });
796→            }
797→            // Decrement pending upload count for this folder
798→            if let Some(entry) = self.publish_queue.get_mut(&result.parent_ino) {
799→                entry.pending_uploads = entry.pending_uploads.saturating_sub(1);
800→            }
801→        }
802→        // Flush any publish queue entries that are ready
803→        self.flush_publish_queue();
804→    }
