806→    /// Queue a folder for debounced metadata publish.
807→    /// Called after mutations (create, unlink, rmdir, rename) that change folder contents.
808→    pub fn queue_publish(&mut self, folder_ino: u64, has_pending_upload: bool) {
809→        let entry = self.publish_queue.entry(folder_ino).or_insert(PublishQueueEntry {
810→            first_dirty: std::time::Instant::now(),
811→            pending_uploads: 0,
812→        });
813→        if has_pending_upload {
814→            entry.pending_uploads += 1;
815→        }
816→        // Mark folder as locally mutated to prevent background refreshes
817→        self.mutated_folders.insert(folder_ino, std::time::Instant::now());
818→    }
819→
820→    /// Flush publish queue entries that are ready.
821→    /// Criteria: all uploads complete AND debounce period elapsed (1.5s),
822→    /// OR safety valve: 10s since first change regardless of pending uploads.
823→    fn flush_publish_queue(&mut self) {
824→        let now = std::time::Instant::now();
825→        let debounce = std::time::Duration::from_millis(1500);
826→        let safety_valve = std::time::Duration::from_secs(10);
827→
828→        // Collect folders ready to publish
829→        let ready: Vec<u64> = self.publish_queue.iter()
830→            .filter(|(_, entry)| {
831→                let elapsed = now.duration_since(entry.first_dirty);
832→                if elapsed >= safety_valve {
833→                    // Safety valve: force publish regardless of pending uploads
834→                    if entry.pending_uploads > 0 {
835→                        log::warn!(
836→                            "Publish safety valve triggered with {} pending upload(s)",
837→                            entry.pending_uploads
838→                        );
839→                    }
840→                    return true;
841→                }
842→                entry.pending_uploads == 0 && elapsed >= debounce
843→            })
844→            .map(|(&ino, _)| ino)
845→            .collect();
846→
847→        for folder_ino in ready {
848→            self.publish_queue.remove(&folder_ino);
849→            match self.build_folder_metadata(folder_ino) {
850→                Ok((metadata, folder_key, ipns_private_key, ipns_name, old_cid)) => {
851→                    spawn_metadata_publish(
852→                        self.api.clone(),
853→                        self.rt.clone(),
854→                        metadata,
855→                        folder_key,
856→                        ipns_private_key,
857→                        ipns_name,
858→                        old_cid,
859→                        self.publish_coordinator.clone(),
860→                    );
861→                }
862→                Err(e) => {
863→                    log::error!("Failed to build folder metadata for publish (ino {}): {}", folder_ino, e);
864→                }
865→            }
866→        }
867→    }
