const parentFolder = getParentFolder();
if (!parentFolder) throw new Error('Parent folder not found');

const performDelete = async (): Promise<{ newSequenceNumber: bigint }> => {
  const freshParent = getParentFolder();
  if (!freshParent) throw new Error('Parent folder not found');
  if (itemType === 'folder') {
    const folders = useFolderStore.getState().folders;
    const { newSequenceNumber } = await folderService.deleteFolder({
      folderId: itemId,
      parentFolderState: freshParent,
      getFolderState: (id) => folders[id],
      unpinCid: unpinFromIpfs,
    });
    return { newSequenceNumber };
  } else {
    const { newSequenceNumber } = await folderService.deleteFileFromFolder({
      fileId: itemId,
      parentFolderState: freshParent,
    });
    return { newSequenceNumber };
  }
};

let deleteResult: { newSequenceNumber: bigint };
try {
  deleteResult = await performDelete();
} catch (err) {
  if (!isConflictError(err)) throw err;
  useSyncStore.getState().setConflict('Folder updated by another device, re-syncing...');
  try {
    await resyncFolder(parentFolder.ipnsName, parentFolder.id);
    await new Promise((r) => setTimeout(r, 100 + Math.random() * 400));
    deleteResult = await performDelete();
  } catch (retryErr) {
    if (isConflictError(retryErr)) {
      throw new Error('Conflict persists after re-sync. Please try again.');

  // 3. Remove folder from parent's children
  children.splice(folderIndex, 1);

  // 4. Update parent folder metadata and publish
  const { newSequenceNumber } = await updateFolderMetadata({
    folderId: params.parentFolderState.id,
    children,
    folderKey: params.parentFolderState.folderKey,
    ipnsPrivateKey: params.parentFolderState.ipnsPrivateKey,
    ipnsName: params.parentFolderState.ipnsName,
    sequenceNumber: params.parentFolderState.sequenceNumber,
  });

  // 5. File CID unpinning and TEE unenrollment deferred to caller
  // The caller (useFolder hook) resolves fileMetaIpnsName -> CID for unpinning.
  // TODO: Phase 14 should add batch unenrollment for orphaned file IPNS records.

  return { fileIpnsNames, newSequenceNumber };
}

