274→  /**
275→   * Move a file or folder to a different parent.
276→   *
277→   * @param itemId - ID of item to move
278→   * @param itemType - 'file' or 'folder'
279→   * @param sourceParentId - Current parent folder ID
280→   * @param destParentId - Destination parent folder ID
281→   */
282→  const handleMove = useCallback(
283→    async (
284→      itemId: string,
285→      itemType: 'file' | 'folder',
286→      sourceParentId: string,
287→      destParentId: string
288→    ): Promise<void> => {
289→      setState({ isLoading: true, error: null });
290→      try {
291→        const getSourceFolder = () => {
292→          const freshState = useFolderStore.getState();
293→          return sourceParentId === 'root'
294→            ? getRootFolderState(useVaultStore.getState(), freshState.folders)
295→            : freshState.folders[sourceParentId];
296→        };
297→
298→        const getDestFolder = () => {
299→          const freshState = useFolderStore.getState();
300→          return destParentId === 'root'
301→            ? getRootFolderState(useVaultStore.getState(), freshState.folders)
302→            : freshState.folders[destParentId];
303→        };
304→
305→        const sourceFolder = getSourceFolder();
306→        const destFolder = getDestFolder();
307→        if (!sourceFolder || !destFolder) {
308→          throw new Error('Source or destination folder not found');
309→        }
310→
311→        const performMove = async (): Promise<{
312→          destSequenceNumber: bigint;
313→          sourceSequenceNumber: bigint;
314→        }> => {
315→          const freshSource = getSourceFolder();
316→          const freshDest = getDestFolder();
317→          if (!freshSource || !freshDest) throw new Error('Source or destination folder not found');
318→          const folders = useFolderStore.getState().folders;
319→          if (itemType === 'folder') {
320→            return await folderService.moveFolder({
321→              folderId: itemId,
322→              sourceFolderState: freshSource,
323→              destFolderState: freshDest,
324→              folders,
325→            });
326→          } else {
327→            return await folderService.moveFile({
328→              fileId: itemId,
329→              sourceFolderState: freshSource,
330→              destFolderState: freshDest,
331→            });
332→          }
333→        };
334→
335→        let moveResult: { destSequenceNumber: bigint; sourceSequenceNumber: bigint };
336→        try {
337→          moveResult = await performMove();
338→        } catch (err) {
339→          if (!isConflictError(err)) throw err;
340→          useSyncStore.getState().setConflict('Folder updated by another device, re-syncing...');
341→          try {
342→            // Re-sync both source and destination folders
343→            await Promise.all([
344→              resyncFolder(sourceFolder.ipnsName, sourceFolder.id),
345→              sourceFolder.id !== destFolder.id
346→                ? resyncFolder(destFolder.ipnsName, destFolder.id)
347→                : Promise.resolve(),
348→            ]);
349→            await new Promise((r) => setTimeout(r, 100 + Math.random() * 400));
350→            moveResult = await performMove();
351→          } catch (retryErr) {
352→            if (isConflictError(retryErr)) {
353→              throw new Error('Conflict persists after re-sync. Please try again.');
354→            }
355→            throw retryErr;
356→          } finally {
357→            useSyncStore.getState().clearConflict();
358→          }
359→        }
360→
361→        // Save the moved item BEFORE updating source children (otherwise it's already gone)
362→        const freshSourceBeforeUpdate = getSourceFolder();
363→        const movedItem = freshSourceBeforeUpdate?.children.find((c) => c.id === itemId);
364→
365→        if (itemType === 'folder') {
366→          // Update the moved folder's parentId in local state
367→          const freshFolders = useFolderStore.getState().folders;
368→          const movedFolder = freshFolders[itemId];
369→          if (movedFolder) {
370→            useFolderStore.getState().setFolder({
371→              ...movedFolder,
372→              parentId: destParentId,
373→            });
374→          }
375→        }
376→
377→        // Update source folder's children (remove item)
378→        if (freshSourceBeforeUpdate) {
379→          const updatedSourceChildren = freshSourceBeforeUpdate.children.filter(
380→            (c) => c.id !== itemId
381→          );
382→          useFolderStore.getState().updateFolderChildren(sourceParentId, updatedSourceChildren);
383→        }
384→
385→        // Update dest folder's children (add item)
386→        const freshDest = getDestFolder();
387→        if (movedItem && freshDest) {
388→          const updatedDestChildren = [
389→            ...freshDest.children,
390→            { ...movedItem, modifiedAt: Date.now() },
391→          ];
392→          useFolderStore.getState().updateFolderChildren(destParentId, updatedDestChildren);
393→        }
394→
395→        // Persist the new sequence numbers so subsequent operations use the correct values
396→        useFolderStore.getState().updateFolderSequence(destParentId, moveResult.destSequenceNumber);
397→        useFolderStore
398→          .getState()
399→          .updateFolderSequence(sourceParentId, moveResult.sourceSequenceNumber);
400→
401→        setState({ isLoading: false, error: null });
402→      } catch (err) {
403→        const error = err instanceof Error ? err.message : 'Failed to move';
404→        setState({ isLoading: false, error });
405→        throw err;
406→      }
407→    },
408→    []
409→  );
